window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-9f4fccb3d1e38e15"]={"versions": [{"id": "FIG-9f4fccb3d1e38e15", "releases": ["R4.0.3", "R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodell-Architektur des AUTOSAR Generic Structure Template (AUTOSAR_TPS_GenericStructureTemplate). Das Diagramm definiert das fundamentale abstrakte Typ- und Prototyp-Strukturmuster («atp»-Pattern: AUTOSAR Template Pattern) für wiederverwendbare, typisierte Modellierungselemente.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Klassendiagramm umfasst fünf Modellelemente:</p>\n<ul class=\"fig-list\">\n<li><code>AtpClassifier</code> (kursiv / abstrakt, spezialisiert <code>Identifiable</code>): Aggregiert via Komposition (gefüllte Raute) <code>0..*</code> abgeleitete Features <code>+/atpFeature</code> mit dem Stereotyp <code>«atpDerived»</code>.</li>\n<li><code>AtpFeature</code> (kursiv / abstrakt, spezialisiert <code>Identifiable</code>): Ziel der Kompositionsbeziehung von <code>AtpClassifier</code>.</li>\n<li><code>AtpStructureElement</code> (kursiv / abstrakt): Generalisiert mehrfach über Vererbungspfeile (geschlossene Hohlpfeilspitzen) sowohl auf <code>AtpClassifier</code> als auch auf <code>AtpFeature</code>.</li>\n<li><code>AtpType</code> (kursiv / abstrakt): Spezialisiert <code>AtpClassifier</code> über Vererbung (Hohlpfeilspitze).</li>\n<li><code>AtpPrototype</code> (kursiv / abstrakt): Spezialisiert <code>AtpFeature</code> über Vererbung (Hohlpfeilspitze) und referenziert über eine gerichtete Assoziation mit Stereotyp <code>«atpAbstract»</code> und Rollennamen <code>+atpType</code> genau eine (<code>1</code>) Instanz von <code>AtpType</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Ablauf- oder Zustandslogik. Die Struktur etabliert das Type-Prototype-Entwurfsmuster: Ein <code>AtpClassifier</code> bzw. <code>AtpType</code> definiert den strukturellen Typ, während <code>AtpFeature</code> bzw. <code>AtpPrototype</code> das typisierte Vorkommen innerhalb eines strukturellen Kontexts repräsentiert. <code>AtpStructureElement</code> vereint dabei Classifier- und Feature-Eigenschaften für hierarchische Verschachtelungen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives Metamodell-Muster des Generic Structure Template. Sämtliche Klassen sind als abstrakte Basiselemente («atp») konzipiert und dürfen in konkreten AUTOSAR-Metamodellen nicht direkt instanziiert werden. Konkrete Metaklassen für Typen müssen von <code>AtpType</code> erben, Instanzelemente/Prototypen von <code>AtpPrototype</code>. Die Kardinalität <code>1</code> am Assoziationsende <code>+atpType</code> verpflichtet jeden Prototyp zur Bindung an genau einen definierenden Typen. Die Komposition <code>+/atpFeature</code> ist als abgeleitet (<code>«atpDerived»</code>, Schrägstrich <code>/</code>) deklariert.</p>"}, {"id": "FIG-56bba552ef696019", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodell-Architektur des AUTOSAR Generic Structure Template (AUTOSAR_TPS_GenericStructureTemplate). Das Diagramm definiert das fundamentale abstrakte Typ- und Prototyp-Strukturmuster («atp»-Pattern: AUTOSAR Template Pattern) für wiederverwendbare, typisierte Modellierungselemente.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Klassendiagramm umfasst fünf Modellelemente:</p>\n<ul class=\"fig-list\">\n<li><code>AtpClassifier</code> (kursiv / abstrakt, spezialisiert <code>Identifiable</code>): Aggregiert via Komposition (gefüllte Raute) <code>0..*</code> abgeleitete Features <code>+/atpFeature</code> mit dem Stereotyp <code>«atpDerived»</code>.</li>\n<li><code>AtpFeature</code> (kursiv / abstrakt, spezialisiert <code>Identifiable</code>): Ziel der Kompositionsbeziehung von <code>AtpClassifier</code>.</li>\n<li><code>AtpStructureElement</code> (kursiv / abstrakt): Generalisiert mehrfach über Vererbungspfeile (geschlossene Hohlpfeilspitzen) sowohl auf <code>AtpClassifier</code> als auch auf <code>AtpFeature</code>.</li>\n<li><code>AtpType</code> (kursiv / abstrakt): Spezialisiert <code>AtpClassifier</code> über Vererbung (Hohlpfeilspitze).</li>\n<li><code>AtpPrototype</code> (kursiv / abstrakt): Spezialisiert <code>AtpFeature</code> über Vererbung (Hohlpfeilspitze) und referenziert über eine gerichtete Assoziation mit Stereotyp <code>«atpAbstract»</code> und Rollennamen <code>+atpType</code> genau eine (<code>1</code>) Instanz von <code>AtpType</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Ablauf- oder Zustandslogik. Die Struktur etabliert das Type-Prototype-Entwurfsmuster: Ein <code>AtpClassifier</code> bzw. <code>AtpType</code> definiert den strukturellen Typ, während <code>AtpFeature</code> bzw. <code>AtpPrototype</code> das typisierte Vorkommen innerhalb eines strukturellen Kontexts repräsentiert. <code>AtpStructureElement</code> vereint dabei Classifier- und Feature-Eigenschaften für hierarchische Verschachtelungen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives Metamodell-Muster des Generic Structure Template. Sämtliche Klassen sind als abstrakte Basiselemente («atp») konzipiert und dürfen in konkreten AUTOSAR-Metamodellen nicht direkt instanziiert werden. Konkrete Metaklassen für Typen müssen von <code>AtpType</code> erben, Instanzelemente/Prototypen von <code>AtpPrototype</code>. Die Kardinalität <code>1</code> am Assoziationsende <code>+atpType</code> verpflichtet jeden Prototyp zur Bindung an genau einen definierenden Typen. Die Komposition <code>+/atpFeature</code> ist als abgeleitet (<code>«atpDerived»</code>, Schrägstrich <code>/</code>) deklariert.</p>"}, {"id": "FIG-2fabd3313370557f", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodell-Architektur des AUTOSAR Generic Structure Template (AUTOSAR_TPS_GenericStructureTemplate). Das Diagramm definiert das fundamentale abstrakte Typ- und Prototyp-Strukturmuster («atp»-Pattern: AUTOSAR Template Pattern) für wiederverwendbare, typisierte Modellierungselemente.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Klassendiagramm umfasst fünf Modellelemente:</p>\n<ul class=\"fig-list\">\n<li><code>AtpClassifier</code> (kursiv / abstrakt, spezialisiert <code>Identifiable</code>): Aggregiert via Komposition (gefüllte Raute) <code>0..*</code> abgeleitete Features <code>+/atpFeature</code> mit dem Stereotyp <code>«atpDerived»</code>.</li>\n<li><code>AtpFeature</code> (kursiv / abstrakt, spezialisiert <code>Identifiable</code>): Ziel der Kompositionsbeziehung von <code>AtpClassifier</code>.</li>\n<li><code>AtpStructureElement</code> (kursiv / abstrakt): Generalisiert mehrfach über Vererbungspfeile (geschlossene Hohlpfeilspitzen) sowohl auf <code>AtpClassifier</code> als auch auf <code>AtpFeature</code>.</li>\n<li><code>AtpType</code> (kursiv / abstrakt): Spezialisiert <code>AtpClassifier</code> über Vererbung (Hohlpfeilspitze).</li>\n<li><code>AtpPrototype</code> (kursiv / abstrakt): Spezialisiert <code>AtpFeature</code> über Vererbung (Hohlpfeilspitze) und referenziert über eine gerichtete Assoziation mit Stereotyp <code>«atpAbstract»</code> und Rollennamen <code>+atpType</code> genau eine (<code>1</code>) Instanz von <code>AtpType</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Ablauf- oder Zustandslogik. Die Struktur etabliert das Type-Prototype-Entwurfsmuster: Ein <code>AtpClassifier</code> bzw. <code>AtpType</code> definiert den strukturellen Typ, während <code>AtpFeature</code> bzw. <code>AtpPrototype</code> das typisierte Vorkommen innerhalb eines strukturellen Kontexts repräsentiert. <code>AtpStructureElement</code> vereint dabei Classifier- und Feature-Eigenschaften für hierarchische Verschachtelungen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives Metamodell-Muster des Generic Structure Template. Sämtliche Klassen sind als abstrakte Basiselemente («atp») konzipiert und dürfen in konkreten AUTOSAR-Metamodellen nicht direkt instanziiert werden. Konkrete Metaklassen für Typen müssen von <code>AtpType</code> erben, Instanzelemente/Prototypen von <code>AtpPrototype</code>. Die Kardinalität <code>1</code> am Assoziationsende <code>+atpType</code> verpflichtet jeden Prototyp zur Bindung an genau einen definierenden Typen. Die Komposition <code>+/atpFeature</code> ist als abgeleitet (<code>«atpDerived»</code>, Schrägstrich <code>/</code>) deklariert.</p>"}, {"id": "FIG-431db3c1bf63e09e", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11", "R21-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodell-Architektur des AUTOSAR Generic Structure Template (AUTOSAR_TPS_GenericStructureTemplate). Das Diagramm definiert das fundamentale abstrakte Typ- und Prototyp-Strukturmuster («atp»-Pattern: AUTOSAR Template Pattern) für wiederverwendbare, typisierte Modellierungselemente.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Klassendiagramm umfasst fünf Modellelemente:</p>\n<ul class=\"fig-list\">\n<li><code>AtpClassifier</code> (kursiv / abstrakt, spezialisiert <code>Identifiable</code>): Aggregiert via Komposition (gefüllte Raute) <code>0..*</code> abgeleitete Features <code>+/atpFeature</code> mit dem Stereotyp <code>«atpDerived»</code>.</li>\n<li><code>AtpFeature</code> (kursiv / abstrakt, spezialisiert <code>Identifiable</code>): Ziel der Kompositionsbeziehung von <code>AtpClassifier</code>.</li>\n<li><code>AtpStructureElement</code> (kursiv / abstrakt): Generalisiert mehrfach über Vererbungspfeile (geschlossene Hohlpfeilspitzen) sowohl auf <code>AtpClassifier</code> als auch auf <code>AtpFeature</code>.</li>\n<li><code>AtpType</code> (kursiv / abstrakt): Spezialisiert <code>AtpClassifier</code> über Vererbung (Hohlpfeilspitze).</li>\n<li><code>AtpPrototype</code> (kursiv / abstrakt): Spezialisiert <code>AtpFeature</code> über Vererbung (Hohlpfeilspitze) und referenziert über eine gerichtete Assoziation mit Stereotyp <code>«atpAbstract»</code> und Rollennamen <code>+atpType</code> genau eine (<code>1</code>) Instanz von <code>AtpType</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Ablauf- oder Zustandslogik. Die Struktur etabliert das Type-Prototype-Entwurfsmuster: Ein <code>AtpClassifier</code> bzw. <code>AtpType</code> definiert den strukturellen Typ, während <code>AtpFeature</code> bzw. <code>AtpPrototype</code> das typisierte Vorkommen innerhalb eines strukturellen Kontexts repräsentiert. <code>AtpStructureElement</code> vereint dabei Classifier- und Feature-Eigenschaften für hierarchische Verschachtelungen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives Metamodell-Muster des Generic Structure Template. Sämtliche Klassen sind als abstrakte Basiselemente («atp») konzipiert und dürfen in konkreten AUTOSAR-Metamodellen nicht direkt instanziiert werden. Konkrete Metaklassen für Typen müssen von <code>AtpType</code> erben, Instanzelemente/Prototypen von <code>AtpPrototype</code>. Die Kardinalität <code>1</code> am Assoziationsende <code>+atpType</code> verpflichtet jeden Prototyp zur Bindung an genau einen definierenden Typen. Die Komposition <code>+/atpFeature</code> ist als abgeleitet (<code>«atpDerived»</code>, Schrägstrich <code>/</code>) deklariert.</p>"}], "trans": [{"from": "FIG-9f4fccb3d1e38e15", "to": "FIG-56bba552ef696019", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-56bba552ef696019", "to": "FIG-2fabd3313370557f", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-2fabd3313370557f", "to": "FIG-431db3c1bf63e09e", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
